CREATE POLICY "Read site profile images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'profile-images');
CREATE POLICY "Admins upload profile images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'profile-images' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update profile images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'profile-images' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'profile-images' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete profile images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'profile-images' AND public.has_role(auth.uid(), 'admin'));